def prop(inp,bg,m):
    H=len(inp);W=len(inp[0]);o=[r[:] for r in inp]
    for r,c in [(r,c) for r in range(H) for c in range(W) if inp[r][c]==m]:
        for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
            rr,cc=r+dr,c+dc
            while 0<=rr<H and 0<=cc<W:
                o[rr][cc]=m; rr+=dr; cc+=dc
    return o
